<section class="poste-hero"><span class="poste-hero-label">Back Office · Municipalité</span><h1 class="page-title">Demandes des citoyens</h1><p>Consultez les dossiers et mettez leur état à jour. Chaque changement déclenche une notification au citoyen.</p></section>
<div class="table-responsive content-panel mt-4"><table class="table align-middle"><thead><tr><th>Référence</th><th>Citoyen / service</th><th>Rendez-vous</th><th>Paiement</th><th>Statut</th><th><?= $peutTraiter?'Action':'Droits' ?></th></tr></thead><tbody><?php foreach($demandes as $d): ?><tr><td>DM-<?= str_pad((string)$d['id_demande'],5,'0',STR_PAD_LEFT) ?><br><small><?= e(date('d/m/Y H:i',strtotime($d['date_depot']))) ?></small></td><td><?= e(trim($d['prenom'].' '.$d['citoyen_nom'])) ?><br><small><?= e($d['email']) ?><br><?= e($d['libelle']) ?></small></td><td><?= $d['date_souhaitee']?e($d['delegation'].', '.$d['gouvernorat'].' · '.date('d/m/Y H:i',strtotime($d['date_souhaitee']))):'Retrait au guichet' ?></td><td><?= e($d['paiement_statut']??'sans frais') ?></td><td><?= e(str_replace('_',' ',$d['statut'])) ?></td><td><?php if($peutTraiter): ?><form method="post" action="index.php?page=admin-demande-municipale-statut" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="id_demande" value="<?= (int)$d['id_demande'] ?>"><select class="form-select form-select-sm" name="statut"><?php foreach(['en_attente','en_cours','approuvee','document_pret','rejetee'] as $s): ?><option value="<?= e($s) ?>" <?= $s===$d['statut']?'selected':'' ?>><?= e(str_replace('_',' ',$s)) ?></option><?php endforeach; ?></select><button class="button button-dark" type="submit">Valider</button></form><?php else: ?><span class="small text-secondary">Consultation seule</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
